------------ define ------------

function CatHouseChooseFriendCatPopup:__init()
    self.selectIndex         = 1
    self.isShowCatTips       = false
    self.friendId2FriendCats = {}
end

function CatHouseChooseFriendCatPopup:__delete()
    self.friendId2FriendCats = nil
end

function CatHouseChooseFriendCatPopup:Awake()
    self:InitData()

end

function CatHouseChooseFriendCatPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        --- 进入这个界面前会拉下好友数据

        local friendList  = self.friends
        local friendCount = #friendList
        self.FriendTextNumber.text = string.format("%s/%s", friendCount, self.maxFriendNum)

        self:FreshFriendList(friendCount)
        self:SwitchLeftPanelShowState()
    end))
    return coWait
end    

function CatHouseChooseFriendCatPopup:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        local co = self:ReloadFriendCatUI()
        if co then
            cs_coroutine.yield_return(co)
        end


    end))
    return coWait
end

function CatHouseChooseFriendCatPopup:OnFocus(focus)
    focus = checkBool(focus)
    KTool.SetActive(self.controller.gameObject, focus)
    if focus then
        CfUtils.SetTopCommonCb(function ()
            if self.isShowCatTips then
                self.isShowCatTips = false
                self:SwitchLeftPanelShowState()
                return
            end
            UIModule.BackDialog()
        end)
    else
        CfUtils.ResetNavigatorCustomBackAction()
    end
end

function CatHouseChooseFriendCatPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function CatHouseChooseFriendCatPopup:InitData()
    ---好友参数表中的好友数量上限
    self.maxFriendNum   = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting11, "FriendArgVo", 1).num)
    --- 训练次数上限（同时也是进化所需数量）
    self.trainTimeLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.TrainTimeLimit).num)

    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local friendList = component:GetFriendList()
    table.sort(friendList, function(a, b)
        return checkNumber(a.catHouseFavorite) > checkNumber(b.catHouseFavorite)
    end)
    self.friends = friendList

end


