function CatHouseChooseFriendCatPopup:ReloadFriendCatUI()
    local friendData = self.friends[self.selectIndex]
    if self.friendId2FriendCats[tostring(friendData.friendId)] then
        self:FreshFriendCatListPanel()
    else
        return self:RequestFriendCats(friendData)
    end
end

function CatHouseChooseFriendCatPopup:RequestFriendCats(friendData)
    return GameUtils.Request(Interfaces.CatHouseFriendCats, {friendId = friendData.friendId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        self.friendId2FriendCats[tostring(friendData.friendId)] = checkTable(response.data.catList)
        self:FreshFriendCatListPanel()

    end)
end

function CatHouseChooseFriendCatPopup:FreshFriendList(friendCount)
    local FriendList = self.FriendList
    if not FriendList.IsListViewInit then
        FriendList:InitGridView(friendCount, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(FriendList, friendCount)
    end
end

function CatHouseChooseFriendCatPopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local node = GetLuaBehaviour(cell.gameObject, CatHouseChooseFriendCatFriendCellEnvPath)
    ---@type CatHouseChooseFriendCatFriendCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetClickBtnCallback(Bind(self, self.OnClickFriendCellAction))
        nodeEnv:SetClickBtnCollectCallback(Bind(self, self.OnClickFriendFavorAction))
    else
        nodeEnv = node.Env
    end
    if nodeEnv then
        local position = index + 1
        local data = self.friends[position]
        nodeEnv:FreshUI(data, position)
        nodeEnv:FreshSelectState(self.selectIndex == position)
    end
    return cell
end

function CatHouseChooseFriendCatPopup:FreshFriendCatListPanel()
    local friendData  = self.friends[self.selectIndex]
    local catListData = self:InitCatListData(friendData)

    -- self.TextFriendName.text = friendData.name
    self:FreshFilterNode(catListData)
end

function CatHouseChooseFriendCatPopup:InitCatListData(friendData)
    local catList    = self.friendId2FriendCats[tostring(friendData.friendId)]
    local t          = {}
    for i, catData in pairs(catList) do
        if  checkNumber(catData.age) == ConstantsCatHouse.BornType.Adult and checkNumber(catData.deliveryRemainTimes) > 0 then
            -- catData.deliveryRemainTimes = deliveryRemainTimes
            table.insert(t, catData)
        end
    end
    -- --- 按培育次数降序
    -- table.sort(t, function(a, b)
    --     return a.deliveryRemainTimes > b.deliveryRemainTimes
    -- end)
    return t
end

function CatHouseChooseFriendCatPopup:FreshFilterNode(catListData)
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if nodeEnv == nil then return end
    nodeEnv:SetFilterClass(Constants.UIFilterType.CatHouse)
    -- nodeEnv:SetExtraParams(checkNumber(self.catHouseHomeDojo.partyCatId))
    nodeEnv:SetCallback(catListData, Bind(self, self.OnClickFilterNode), Constants.UISortType.CatHouseFriend)
    nodeEnv:RestoreState("CatHouseChooseFriendCatPopup", Bind(self, self.OnClickFilterNode))
end

function CatHouseChooseFriendCatPopup:FreshListUI()
    local len  = #self.catList
    local List = self.FriendCatList
    if not List.mLoopListView.IsListViewInit then
        List:InitListView(len, Bind(self, self.OnGetCatItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseChooseFriendCatPopup:OnGetCatItemByIndex(cell, index)
    if index < 0 then
        return nil
    end

    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then
        return nil
    end
    
    local position         = index + 1
    nodeEnv:SetCallback(Bind(self, self.OnClickCatNodeAction))
    nodeEnv:FreshCommonUI(self.catList[position])
    nodeEnv:FreshTimes(self.trainTimeLimit)

    return cell

end

---FreshFriendCatListShowState
---刷新好友猫列表显示状态
function CatHouseChooseFriendCatPopup:SwitchLeftPanelShowState()
    KTool.SetActive(self.FriendListPanel.gameObject, not self.isShowCatTips)
    KTool.SetActive(self.CatHouseTipsNode.gameObject, self.isShowCatTips)
end


