---OnClickFriendCellAction
---@param position number
---@param childEnv CatHouseChooseFriendCatFriendCell
function CatHouseChooseFriendCatPopup:OnClickFriendCellAction(position, childEnv)
    if self.selectIndex == position then return end

    local item = self.FriendList:GetShownItemByItemIndex(self.selectIndex - 1)
    ---@type CatHouseChooseFriendCatFriendCell
    local env = CfUtils.GetLuaScr(item, CatHouseChooseFriendCatFriendCellEnvPath)
    if not isNull(env) then
        env:FreshSelectState(false)
    end
    childEnv:FreshSelectState(true)

    self.selectIndex = position

    self:ReloadFriendCatUI()

end

---OnClickFriendFavorAction
---@param position number
---@param childEnv CatHouseChooseFriendCatFriendCell
function CatHouseChooseFriendCatPopup:OnClickFriendFavorAction(position, childEnv)
    local friendData = self.friends[position]
    local catHouseFavorite = checkNumber(friendData.catHouseFavorite)
    GameUtils.Request(Interfaces.CatHouseSetFavorFriend, {friendId = friendData.friendId}, function(req, response)
        catHouseFavorite = catHouseFavorite == 0 and 1 or 0
        friendData.catHouseFavorite = catHouseFavorite

        childEnv:FreshFavorUI(catHouseFavorite)
    end)
end

---OnClickCatNodeAction
---@param catData table 好友数据 {
---     id:int 猫唯一id
---     playerId:int 玩家id
---     catId:int 配表Id
---     name:string 名字
---     birthday:string 生日
---     age:int 1幼年，2成年
---     attr:map kv结构，k=属性，v=值
---     hp:int 体力值
---     nextHpSeconds:int 下一点体力恢复剩余秒数
---     genes:list 基因列表
---          \--geneId:int 基因id
---          \--skillId:int 技能id
---          \--additions:int 增加值
---     deliveryRemainTimes:int 剩余孵化次数
---     status:map 当前猫咪状态 KEY: 1:集会登记 2:吃撑 3:恢复 4:孵化 5:培育等待请求 6:探索 VALUE:剩余秒数
---     isShow:int 是否显示在猫屋中
---     trainingTimes:int 训练次数
---}
function CatHouseChooseFriendCatPopup:OnClickCatNodeAction(catData)

    local friendData = self.friends[self.selectIndex]
    ---@type CatHouseTipsNode
    local env = CfUtils.GetLuaScr(self.CatHouseTipsNode, "Game.CatHouse.CatHouseTipsNode")
    if isNull(env) then
        return
    end

    if not self.isShowCatTips then
        self.isShowCatTips = true
        self:SwitchLeftPanelShowState()
    end

    env:FreshUI(catData, ConstantsCatHouse.CatListType.ChooseFriend, function()
        if catData.age == ConstantsCatHouse.BornType.Baby then
            GameUtils.Toast(localize("幼年期不能培育"))
            return
        end
        if checkNumber(catData.deliveryRemainTimes) <= 0 then
            GameUtils.Toast(localize("培育次数不足"))
            return
        end
        KCookie.Set(CookieOtherCatInfoName, {otherCatData = catData, otherCatOwnerInfo = friendData, matchType = 1})
        UIModule.BackDialog()
    end, nil, {
        {id = Constants.UITypeIds.CatHouseChooseFriendCatPopup}
    }, friendData)

end

